insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  16,
  $wyb$A retrieval-augmented generation (RAG) service: your documentation is chunked, embedded locally with sentence-transformers (free, no API key), and stored in Pinecone; a FastAPI endpoint retrieves the most relevant chunks for any question and asks the AI to answer using only that context, with source citations. A source guard makes sure the bot can never claim to have used a document it wasn't actually given, and returns an honest 'I don't have that information' instead of guessing.$wyb$,
  $wyl$[
  "Chunk documents into overlapping word-based windows, and prove the overlap actually works with real word-boundary tests",
  "Generate embeddings locally with sentence-transformers - no API key, no per-call cost",
  "Set up and query a Pinecone vector index for semantic search",
  "Build a RAG prompt that grounds answers in retrieved context and refuses to guess outside it",
  "Guard the sources a bot claims to have used against what it actually retrieved",
  "Expose a chat endpoint with FastAPI and deploy it"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "130 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A free Pinecone account and API key",
    "4-6 of your real docs/FAQs/policy pages saved as plain .txt or .md files"
  ],
  "outcomes": [
    "Chunk documents into overlapping windows and prove the overlap is real with actual word-boundary tests",
    "Generate embeddings locally with sentence-transformers, at zero per-call cost",
    "Store and query a Pinecone vector index for semantic search over your own docs",
    "Have the AI answer using ONLY retrieved context, with a guard that catches a fallback answer wrongly citing sources",
    "Expose it as a FastAPI /chat endpoint and deploy it"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Prepare your knowledge base and Pinecone index",
      "time": "20 min",
      "description": "Clean inputs make or break a RAG bot - start here, before writing any retrieval code.",
      "steps": [
        {
          "instruction": "Create a `docs/` folder and save 4-6 of your real product docs, FAQs, or policy pages as plain .txt or .md files. Strip out navigation menus, headers, and boilerplate - keep just the actual content.",
          "verify": "Open each file and confirm it reads as clean prose, not a copy-pasted webpage with a nav bar and cookie banner text mixed in."
        },
        {
          "instruction": "In Pinecone, create a free account and a new index with dimension 384 (to match the all-MiniLM-L6-v2 embedding model this project uses). Copy your API key and index name into .env.",
          "verify": "Open the Pinecone console and confirm your new index shows dimension 384 and 0 vectors so far."
        }
      ],
      "goFurther": "Skim your docs and note 3-5 questions a real customer might ask that your docs should be able to answer - you'll use these to test retrieval in Build 3."
    },
    {
      "number": 2,
      "title": "Chunk, embed, and upload your docs",
      "time": "40 min",
      "description": "Turn your documents into searchable vectors. The chunking logic is pure Python, tested with real word-boundary checks; embedding runs locally on your machine for free; only the final upload needs your Pinecone account.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# Pinecone - create a free account at pinecone.io, then a new\n# index with dimension 384\nPINECONE_API_KEY=paste_your_own_key_here\nPINECONE_INDEX=support-kb\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `chunker.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Customer Support RAG Bot (part 1).\n\nSplits a document into overlapping word-based chunks small enough to\nembed and retrieve individually. Pure function, no network call - fully\ntestable without Pinecone, sentence-transformers, or any API key.\n\"\"\"\n\n\ndef chunk_text(text, chunk_size=200, overlap=40):\n    \"\"\"\n    Splits text into word-based chunks of chunk_size words, with overlap\n    words shared between consecutive chunks.\n\n        chunk_text(\"word1 word2 ... word500\", chunk_size=200, overlap=40)\n\n    The overlap exists so a sentence that happens to fall right on a\n    chunk boundary doesn't get split across two chunks with neither one\n    containing the whole idea - each chunk after the first repeats the\n    last `overlap` words of the one before it.\n\n    200 words (not the 512 used for some other embedding tasks) retrieves\n    more precisely for a support bot, where a customer question usually\n    maps to one specific paragraph, not several.\n    \"\"\"\n    words = text.split()\n    if not words:\n        return []\n\n    step = chunk_size - overlap\n    if step <= 0:\n        raise ValueError(\"overlap must be smaller than chunk_size\")\n\n    chunks = []\n    for start in range(0, len(words), step):\n        chunk_words = words[start:start + chunk_size]\n        chunks.append(\" \".join(chunk_words))\n        if start + chunk_size >= len(words):\n            break\n\n    return chunks\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the chunking logic works:\n    #     python chunker.py\n    words = [f\"word{i}\" for i in range(50)]\n    text = \" \".join(words)\n\n    chunks = chunk_text(text, chunk_size=20, overlap=5)\n    print(f\"Split 50 words (chunk_size=20, overlap=5) into {len(chunks)} chunks:\")\n    for i, chunk in enumerate(chunks):\n        print(f\"  chunk {i}: {len(chunk.split())} words\")\n\n    assert len(chunks) == 3\n    print(\"\\nChecking the overlap is real...\")\n    chunk0_end = chunks[0].split()[-5:]\n    chunk1_start = chunks[1].split()[:5]\n    assert chunk0_end == chunk1_start\n    print(\"  OK - the last 5 words of chunk 0 match the first 5 words of chunk 1\")\n\n    print(\"\\nChecking every word from the original text appears in at least one chunk...\")\n    all_chunked_words = set()\n    for chunk in chunks:\n        all_chunked_words.update(chunk.split())\n    assert all_chunked_words == set(words)\n    print(\"  OK - no word was dropped by the chunking\")\n\n    print(\"\\nChecking a short document (fewer words than chunk_size) returns one chunk...\")\n    short = chunk_text(\"just six words in this sentence\", chunk_size=200, overlap=40)\n    assert len(short) == 1\n    assert short[0] == \"just six words in this sentence\"\n    print(\"  OK -\", short)\n\n    print(\"\\nChecking empty text returns an empty list, not a crash...\")\n    assert chunk_text(\"\", chunk_size=200, overlap=40) == []\n    print(\"  OK\")\n\n    print(\"\\nAll chunking checks passed.\")\n",
          "verify": "Run `python chunker.py`. You should see 50 words split into 3 chunks, then confirmation the overlap is real (last 5 words of chunk 0 match the first 5 of chunk 1), that no word from the original text was dropped, that a short document returns exactly one chunk, and that empty text returns an empty list - ending with `All chunking checks passed.`"
        },
        {
          "instruction": "Create `embed.py` with this code. The first run downloads a ~90MB model (needs internet once), then everything after runs fully offline with no API key:",
          "prompt": "\"\"\"\nStep 2 of the Customer Support RAG Bot (part 2).\n\nTurns text chunks into vectors using sentence-transformers, entirely on\nyour own machine - no API key, no per-call cost, and it works even with\nyour internet disconnected after the model's first download.\n\"\"\"\n\nfrom sentence_transformers import SentenceTransformer\n\n# Loaded once at import time, not inside embed() - reloading a ~90MB\n# model on every single call would make ingesting even a handful of\n# documents painfully slow. The first import downloads and caches it;\n# every import after that loads instantly from disk.\n_MODEL = SentenceTransformer(\"all-MiniLM-L6-v2\")\n\nEMBEDDING_DIMENSIONS = 384\n\n\ndef embed(texts):\n    \"\"\"\n    Turns a list of text strings into a list of 384-dimensional vectors.\n\n        vectors = embed([\"How do I reset my password?\", \"Refund policy details\"])\n\n    Batches the whole list into one encode() call rather than looping\n    one text at a time - meaningfully faster for anything more than a\n    couple of texts, since the model processes a batch in parallel\n    internally.\n    \"\"\"\n    return _MODEL.encode(texts).tolist()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check embedding works. This downloads\n    # the ~90MB model on first run (needs internet once), then runs\n    # fully locally - no API key needed:  python embed.py\n    vectors = embed([\"How do I reset my password?\", \"What is your refund policy?\"])\n\n    assert len(vectors) == 2\n    assert len(vectors[0]) == EMBEDDING_DIMENSIONS\n    print(f\"Embedded 2 texts into {len(vectors)} vectors of {len(vectors[0])} dimensions each.\")\n\n    print(\"\\nChecking that similar questions produce more similar vectors than unrelated ones...\")\n    import math\n\n    def cosine_similarity(a, b):\n        dot = sum(x * y for x, y in zip(a, b))\n        norm_a = math.sqrt(sum(x * x for x in a))\n        norm_b = math.sqrt(sum(y * y for y in b))\n        return dot / (norm_a * norm_b)\n\n    password_q1, password_q2, refund_q = embed([\n        \"How do I reset my password?\",\n        \"How can I change my password?\",\n        \"What is your refund policy?\",\n    ])\n\n    similar_score = cosine_similarity(password_q1, password_q2)\n    unrelated_score = cosine_similarity(password_q1, refund_q)\n    print(f\"  Similarity between two password questions: {similar_score:.3f}\")\n    print(f\"  Similarity between a password and a refund question: {unrelated_score:.3f}\")\n    assert similar_score > unrelated_score\n    print(\"  OK - semantically similar questions scored more similar than unrelated ones\")\n\n    print(\"\\nAll embedding checks passed.\")\n",
          "verify": "Run `python embed.py`. You should see 2 texts embedded into 384-dimension vectors, then a similarity check showing two differently-worded password questions score MORE similar to each other than to an unrelated refund question - ending with `All embedding checks passed.`"
        },
        {
          "instruction": "Create `ingest.py` with this code, then run it for real against your docs/ folder:",
          "prompt": "\"\"\"\nStep 2 of the Customer Support RAG Bot (part 3).\n\nReads every file in your docs/ folder, chunks and embeds each one, and\nupserts the vectors into Pinecone. This is the one part of Build 2 that\nneeds a real Pinecone account - chunking and embedding are already\ntested without one.\n\"\"\"\n\nimport os\n\nfrom chunker import chunk_text\nfrom dotenv import load_dotenv\nfrom embed import embed\nfrom pinecone import Pinecone\n\nload_dotenv()\n\n\ndef build_records(folder=\"docs\"):\n    \"\"\"\n    Reads every file in folder, chunks it, and returns a list of\n    {\"id\", \"text\", \"source\"} dicts ready to embed and upsert.\n\n    Does read from disk, but makes no network call - kept separate from\n    the actual Pinecone upsert so you can inspect exactly what would be\n    uploaded before spending a Pinecone write on it.\n    \"\"\"\n    records = []\n    for filename in sorted(os.listdir(folder)):\n        path = os.path.join(folder, filename)\n        if not os.path.isfile(path):\n            continue\n        with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n            text = f.read()\n\n        for i, chunk in enumerate(chunk_text(text)):\n            records.append({\"id\": f\"{filename}-{i}\", \"text\": chunk, \"source\": filename})\n\n    return records\n\n\ndef ingest_docs(folder=\"docs\"):\n    \"\"\"\n    The main function. Chunks and embeds every file in folder, and\n    upserts them all to your Pinecone index. Returns how many chunks\n    were upserted.\n    \"\"\"\n    records = build_records(folder)\n    if not records:\n        raise ValueError(f\"No files found in '{folder}/' - add your docs there first.\")\n\n    vectors = embed([r[\"text\"] for r in records])\n\n    pc = Pinecone(api_key=os.environ[\"PINECONE_API_KEY\"])\n    index = pc.Index(os.environ.get(\"PINECONE_INDEX\", \"support-kb\"))\n\n    to_upsert = [\n        (record[\"id\"], vector, {\"text\": record[\"text\"], \"source\": record[\"source\"]})\n        for record, vector in zip(records, vectors)\n    ]\n    index.upsert(vectors=to_upsert)\n\n    return len(to_upsert)\n\n\nif __name__ == \"__main__\":\n    # This file's core logic (build_records) is checked without Pinecone\n    # or an embedding model - only ingest_docs() itself needs both:\n    #     python ingest.py\n    import tempfile\n\n    print(\"Checking build_records() against real temp files...\")\n    tmp_dir = tempfile.mkdtemp()\n    with open(os.path.join(tmp_dir, \"faq.txt\"), \"w\", encoding=\"utf-8\") as f:\n        f.write(\" \".join(f\"word{i}\" for i in range(30)))\n\n    records = build_records(tmp_dir)\n    assert len(records) == 1  # 30 words fits in one default-sized (200-word) chunk\n    assert records[0][\"id\"] == \"faq.txt-0\"\n    assert records[0][\"source\"] == \"faq.txt\"\n    print(\"  OK -\", records[0][\"id\"], \"-\", len(records[0][\"text\"].split()), \"words\")\n\n    print(\"\\nAll offline checks passed. Run ingest_docs() for real against your docs/ folder\")\n    print(\"and your actual Pinecone index once your .env is set up.\")\n",
          "verify": "Run `python ingest.py` first (checks build_records() against a real temp file, no Pinecone needed), then run `python -c \"from ingest import ingest_docs; print('Upserted', ingest_docs(), 'chunks')\"`. Check the Pinecone console - your index should now show that many vectors."
        }
      ],
      "goFurther": "🛠️ Re-run the ingest command after editing one doc - confirm the vector count doesn't double (Pinecone upserts overwrite by ID, so editing a file and re-ingesting should leave the count roughly the same, not add duplicates)."
    },
    {
      "number": 3,
      "title": "Build the grounded RAG query engine",
      "time": "35 min",
      "description": "This is the anti-hallucination core - answers come only from retrieved context, and the sources the bot claims to have used are checked against what was actually retrieved, never just trusted.",
      "steps": [
        {
          "instruction": "Create `rag.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Customer Support RAG Bot.\n\nThis is the anti-hallucination core: retrieve the most relevant chunks\nfor a question, then tell the AI to answer using ONLY that context. It\nalso carries this project's safety guard - the sources list returned to\nthe caller is checked against what was ACTUALLY retrieved, so the bot\ncan never claim it used a document it never saw.\n\"\"\"\n\nimport os\n\nfrom dotenv import load_dotenv\nfrom embed import embed\nfrom pinecone import Pinecone\nfrom sdt_ai import ask_ai\n\nload_dotenv()\n\nTOP_K = 5\nFALLBACK_PHRASE = \"I don't have that information -- let me connect you with a human agent.\"\n\n\ndef _get_index():\n    pc = Pinecone(api_key=os.environ[\"PINECONE_API_KEY\"])\n    return pc.Index(os.environ.get(\"PINECONE_INDEX\", \"support-kb\"))\n\n\ndef retrieve(question, top_k=TOP_K):\n    \"\"\"\n    Embeds the question and returns the top_k most similar chunks from\n    Pinecone as a list of {\"text\", \"source\"} dicts.\n    \"\"\"\n    index = _get_index()\n    vector = embed([question])[0]\n    results = index.query(vector=vector, top_k=top_k, include_metadata=True)\n    return [\n        {\"text\": match.metadata[\"text\"], \"source\": match.metadata[\"source\"]}\n        for match in results.matches\n    ]\n\n\ndef build_prompt(question, chunks):\n    \"\"\"Pure function, no network call - tested below against fake chunks.\"\"\"\n    context = \"\\n\\n\".join(f\"[{c['source']}]: {c['text']}\" for c in chunks)\n    return f\"\"\"Answer the customer's question using ONLY the context below.\n\nIf the answer is not in the context, respond with EXACTLY this sentence\nand nothing else: \"{FALLBACK_PHRASE}\"\n\nDo not use any outside knowledge, and do not guess.\n\nCONTEXT:\n{context}\n\nQUESTION: {question}\"\"\"\n\n\ndef validate_sources(answer, retrieved_chunks):\n    \"\"\"\n    Returns the list of source filenames the answer is allowed to cite.\n\n        validate_sources(\"some real answer\", [{\"source\": \"faq.txt\"}, ...])\n\n    Every filename actually retrieved for this question is a valid\n    citation - the one thing this guards against is the FALLBACK case:\n    if the AI said it doesn't have the information, the sources list\n    must come back empty, even though chunks were technically retrieved,\n    because none of them were actually used in the answer.\n    \"\"\"\n    if answer.strip() == FALLBACK_PHRASE:\n        return []\n    seen = []\n    for chunk in retrieved_chunks:\n        if chunk[\"source\"] not in seen:\n            seen.append(chunk[\"source\"])\n    return seen\n\n\ndef answer_question(question):\n    \"\"\"\n    The main function. Give it a customer question, get back:\n\n        {\"answer\": \"...\", \"sources\": [\"faq.txt\", \"returns-policy.md\"]}\n\n    sources is always a subset of what was actually retrieved for this\n    specific question - never invented, and always empty for a fallback\n    answer.\n    \"\"\"\n    chunks = retrieve(question)\n    if not chunks:\n        return {\"answer\": FALLBACK_PHRASE, \"sources\": []}\n\n    prompt = build_prompt(question, chunks)\n    answer = ask_ai(prompt, max_tokens=400, project=\"support-rag-bot\")\n\n    return {\"answer\": answer, \"sources\": validate_sources(answer, chunks)}\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the prompt-building and source\n    # guard work - no AI call, no Pinecone account needed:  python rag.py\n\n    fake_chunks = [\n        {\"text\": \"Refunds are processed within 5-7 business days.\", \"source\": \"refunds.md\"},\n        {\"text\": \"Refunds are only available within 30 days of purchase.\", \"source\": \"refunds.md\"},\n        {\"text\": \"Password resets are self-service via the login page.\", \"source\": \"account.md\"},\n    ]\n\n    print(\"Checking build_prompt()...\")\n    prompt = build_prompt(\"How long do refunds take?\", fake_chunks)\n    assert \"[refunds.md]\" in prompt\n    assert \"5-7 business days\" in prompt\n    assert FALLBACK_PHRASE in prompt\n    print(\"  OK - context and fallback instruction both correctly included\")\n\n    print(\"\\nChecking validate_sources() with a real answer...\")\n    sources = validate_sources(\"Refunds take 5-7 business days.\", fake_chunks)\n    assert sources == [\"refunds.md\", \"account.md\"]\n    print(\"  OK - unique retrieved sources returned in order:\", sources)\n\n    print(\"\\nChecking validate_sources() with the fallback phrase...\")\n    sources = validate_sources(FALLBACK_PHRASE, fake_chunks)\n    assert sources == []\n    print(\"  OK - fallback answer correctly returns an empty sources list, even though chunks were retrieved\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python rag.py` (no AI call, no Pinecone account needed - this only tests prompt-building and the source guard against fake chunks). You should see the context and fallback instruction correctly included in the prompt, the real-answer case returning the two unique retrieved sources in order, and the fallback-phrase case correctly returning an empty sources list even though chunks were retrieved - ending with `All checks passed.`"
        },
        {
          "instruction": "Now ask it a real question from your Build 1 notes:",
          "prompt": "python -c \"from rag import answer_question; import json; print(json.dumps(answer_question('your test question here'), indent=2))\"",
          "verify": "You should get back a correct answer citing the right source file(s). Then try a question totally unrelated to your docs (e.g. \"what's the capital of France?\") - it should return the exact fallback phrase with an empty sources list, NOT make something up."
        }
      ],
      "goFurther": "Ask a question that's only partially covered by your docs - does the AI answer the covered part and flag the gap, or does it quietly fill in the rest from outside knowledge? Tighten build_prompt()'s wording if it's guessing."
    },
    {
      "number": 4,
      "title": "Expose it as an API and deploy",
      "time": "35 min",
      "description": "Make the bot reachable from anywhere - your website, Slack, or another agent.",
      "steps": [
        {
          "instruction": "Create `main.py` with this code, then run it locally:",
          "prompt": "\"\"\"\nStep 4 of the Customer Support RAG Bot - exposes answer_question() as a\nFastAPI endpoint you can call from a website, Slack bot, or curl.\n\nRun it with:  uvicorn main:app --reload\n\"\"\"\n\nfrom fastapi import FastAPI\nfrom pydantic import BaseModel\nfrom rag import answer_question\nfrom sdt_ai import AIError\n\napp = FastAPI()\n\n\nclass ChatRequest(BaseModel):\n    question: str\n\n\n@app.post(\"/chat\")\ndef chat(request: ChatRequest):\n    question = request.question.strip()\n    if not question:\n        return {\"answer\": \"Please ask a question.\", \"sources\": []}\n\n    try:\n        return answer_question(question)\n    except AIError as problem:\n        return {\"answer\": f\"AI request failed: {problem}\", \"sources\": []}\n\n\n@app.get(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\n\nif __name__ == \"__main__\":\n    print(\"This is a FastAPI app - run it with: uvicorn main:app --reload\")\n    print('Then POST to http://localhost:8000/chat with {\"question\": \"...\"}')\n",
          "verify": "Run `uvicorn main:app --reload`, then in another terminal: `curl -X POST http://localhost:8000/chat -H \"Content-Type: application/json\" -d \"{\\\"question\\\": \\\"your test question\\\"}\"`. You should get back the same {\"answer\": ..., \"sources\": [...]} shape you saw in Build 3."
        },
        {
          "instruction": "Create a `Procfile` with this content, then push your project to GitHub, connect the repo to Railway, and set AI_PROVIDER, GEMINI_API_KEY (or ANTHROPIC_API_KEY), PINECONE_API_KEY, and PINECONE_INDEX in Railway's Variables tab:",
          "prompt": "web: uvicorn main:app --host 0.0.0.0 --port $PORT\n",
          "verify": "Once deployed, POST a test question to your Railway URL's /chat endpoint (same curl command as above, with your Railway URL instead of localhost) and confirm you get the same grounded answer with sources as locally."
        }
      ],
      "goFurther": "🛠️🛠️ Add a `/feedback` endpoint that logs which questions got the fallback phrase, appending each one to a text file - over time this becomes a list of real gaps in your documentation."
    }
  ],
  "portfolio": "You just built a production-pattern RAG service -- the same architecture behind most \"chat with your docs\" products -- with a source guard that keeps its citations honest. Take a screenshot of a real Q&A exchange with sources, and add \"Customer Support RAG Bot\" to your build portfolio.",
  "portfolioPrompt": "I just built a RAG-based customer support bot: my documentation is chunked and embedded locally with sentence-transformers, stored in Pinecone, and a FastAPI endpoint retrieves the most relevant chunks for any question and has the AI answer using ONLY that context, with a source guard that keeps citations honest and an explicit fallback instead of guessing -- deployed live.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"
}$sess$::jsonb,
  null, null,
  $tsh$[
  {
    "issue": "Pinecone 'index not found' error",
    "fix": "The index name or environment/region in your .env doesn't match where you actually created it in the Pinecone dashboard - double check PINECONE_INDEX exactly matches the index name shown in the console."
  },
  {
    "issue": "AI request failed: No AI provider configured",
    "fix": "Add either AI_PROVIDER=gemini plus GEMINI_API_KEY=... (free, from aistudio.google.com/apikey), or AI_PROVIDER=claude plus ANTHROPIC_API_KEY=... (from console.anthropic.com/settings/keys) to your .env file, in the same folder as sdt_ai.py."
  },
  {
    "issue": "Answers are inaccurate or the bot answers from outside knowledge",
    "fix": "Check retrieval first - call retrieve(question) directly and print the chunks it actually found before assuming the AI's answer generation is at fault. Bad retrieval (irrelevant chunks) is the most common root cause in RAG systems, not a bad prompt."
  },
  {
    "issue": "The FastAPI endpoint is slow to respond",
    "fix": "Embedding, Pinecone retrieval, and the AI call run one after another. Time each step separately (wrap each in a simple `time.time()` before/after) to find which one is actually the bottleneck before optimizing blindly - a cold-started embedding model on the very first request is a common one-time cause."
  },
  {
    "issue": "Retrieved chunks cut sentences off awkwardly",
    "fix": "Increase `overlap` in chunker.py's chunk_text() call, or lower chunk_size so chunks map more closely to individual paragraphs, so related sentences are more likely to land fully inside one chunk."
  },
  {
    "issue": "answer_question() returns sources for a fallback-style answer you wrote yourself in testing",
    "fix": "validate_sources() only recognises the EXACT fallback text in FALLBACK_PHRASE - if you're testing with an answer that merely resembles it (e.g. rephrased or with different punctuation), it won't be recognised as a fallback and its sources won't be cleared. This is intentional: the check is deliberately exact, not fuzzy, so it can't misfire on a genuine answer that happens to sound uncertain."
  }
